// Tree-sitter parser loader for the SP10 application graph — zero runtime dependencies, Node >= 20.
// Loads the VENDORED web-tree-sitter ESM loader + WASM grammars from skills/audit/vendor/tree-sitter/
// (regenerated by build-grammars.mjs, verified by .github/scripts/check-vendor.mjs). node_modules is
// never consulted at runtime. The grammars are committed gzipped (tree-sitter-<id>.wasm.gz) to stay
// under the vendor size budget; loadLanguage gunzips them (node:zlib) and hands the bytes to the loader.
//
// Exports: VENDOR_DIR, LANG_IDS, langIdForFile, loadLanguage, parseSource, parserAvailable.
// loadLanguage/parseSource reject when the parser cannot load; callers that must degrade gracefully
// ask parserAvailable() first — it never throws. A Tree returned by parseSource is owned by the
// caller (WASM memory): call tree.delete() when done with it.
import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { gunzipSync } from "node:zlib";
import { join, dirname, extname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const VENDOR_DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "vendor", "tree-sitter");

export const LANG_IDS = ["javascript", "typescript", "tsx", "python", "java", "php", "c_sharp"];

const LOADER_FILE = "web-tree-sitter.mjs";
const RUNTIME_WASM = "tree-sitter.wasm";

const EXT_TO_LANG = {
  ".js": "javascript", ".mjs": "javascript", ".cjs": "javascript", ".jsx": "javascript",
  ".ts": "typescript", ".mts": "typescript", ".cts": "typescript",
  ".tsx": "tsx",
  ".py": "python",
  ".java": "java",
  ".php": "php",
  ".cs": "c_sharp"
};

export function langIdForFile(relPath) {
  return EXT_TO_LANG[extname(relPath).toLowerCase()] ?? null;
}

// Parser.init is process-global: initialise once, and let a failed attempt be retried rather than
// caching the rejection. Languages are memoised per id on top of it.
let runtimePromise = null;
const languagePromises = new Map();

function loadRuntime(vendorDir) {
  if (!runtimePromise) {
    runtimePromise = (async () => {
      const mod = await import(pathToFileURL(join(vendorDir, LOADER_FILE)).href);
      await mod.Parser.init({ locateFile: () => join(vendorDir, RUNTIME_WASM) });
      return mod;
    })().catch((err) => {
      runtimePromise = null;
      throw err;
    });
  }
  return runtimePromise;
}

export async function loadLanguage(langId, { vendorDir = VENDOR_DIR } = {}) {
  if (!LANG_IDS.includes(langId)) throw new Error(`unsupported language id: ${langId}`);
  if (!languagePromises.has(langId)) {
    const promise = (async () => {
      const { Language } = await loadRuntime(vendorDir);
      const wasm = gunzipSync(await readFile(join(vendorDir, `tree-sitter-${langId}.wasm.gz`)));
      return Language.load(wasm); // a Buffer is a Uint8Array: Language.load takes bytes as well as a path
    })().catch((err) => {
      languagePromises.delete(langId);
      throw err;
    });
    languagePromises.set(langId, promise);
  }
  return languagePromises.get(langId);
}

export async function parseSource(langId, sourceText, { vendorDir = VENDOR_DIR } = {}) {
  const language = await loadLanguage(langId, { vendorDir });
  const { Parser } = await loadRuntime(vendorDir);
  const parser = new Parser();
  try {
    parser.setLanguage(language);
    return parser.parse(sourceText);
  } finally {
    parser.delete();
  }
}

// parserAvailable reasons are fixed strings: the reason reaches graph.json's envelope and report.json,
// so it must never carry the (absolute, machine-specific) vendorDir or a loader error message.
export const PARSER_UNAVAILABLE = Object.freeze({ missing: "vendored parser files missing", initFailed: "parser init failed" });

export async function parserAvailable({ vendorDir = VENDOR_DIR } = {}) {
  // Check the files first: a Parser.init pointed at a missing path must never run, because init is
  // process-global and a failed attempt could leave later loads from the real vendor dir broken.
  for (const file of [LOADER_FILE, RUNTIME_WASM]) {
    if (!existsSync(join(vendorDir, file))) return { ok: false, reason: PARSER_UNAVAILABLE.missing };
  }
  try {
    await loadLanguage("javascript", { vendorDir });
    return { ok: true };
  } catch {
    return { ok: false, reason: PARSER_UNAVAILABLE.initFailed };
  }
}
